.panel {
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: clamp(.7rem, 1.4vw, 1.1rem);
  padding: clamp(.75rem, 1.4vw, 1.2rem);
  backdrop-filter: blur(4px);
}

.bullets {
  margin: 0;
  padding-left: clamp(1rem, 2.1vw, 1.45rem);
  display: grid;
  gap: clamp(.45rem, .9vw, .75rem);
