  line-height: 1.35;
}

.two-col {
  display: grid;
  grid-template-columns: 1.12fr .88fr;
  gap: clamp(.7rem, 1.6vw, 1.35rem);
  min-height: 0;
}

.diagram-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(.5rem, 1vw, .9rem);
  align-items: stretch;
  margin-top: clamp(.7rem, 1.3vw, 1rem);
}

.stage {
  position: relative;
  padding: clamp(.55rem, 1vw, .8rem);
  border-radius: .8rem;
  border: 1px solid rgba(122,162,255,.32);
  background: rgba(17, 29, 53, .7);
}
.stage .num {
  font-family: 'IBM Plex Mono', monospace;
  color: var(--accent);
