  font-size: clamp(.66rem, .95vw, .84rem);
  margin-top: clamp(.45rem, 1vw, .9rem);
}

.hero {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: clamp(.8rem, 1.8vw, 1.4rem);
